export const archiveDescriptions = {
  'celestial-atlas': ['Карта звёзд, которую невозможно сложить обратно. Как и любую карту.', 'A star map that cannot be folded back. Like every map.', 'מפת כוכבים שאי אפשר לקפל בחזרה. כמו כל מפה.', 'Un mapa estelar que no hay manera de volver a doblar. Como cualquier mapa.', 'Une carte des étoiles impossible à replier. Comme toutes les cartes.'],
  'visitors-at-orbit': ['Гости прибыли без предупреждения, но с пирогом. Пирог пока изучают.', 'The guests arrived unannounced but with a pie. The pie is still being studied.', 'האורחים הגיעו בלי הודעה, אבל עם עוגה. העוגה עדיין נבדקת.', 'Los invitados llegaron sin avisar, pero con una tarta. La tarta sigue en estudio.', 'Les invités sont arrivés sans prévenir, mais avec une tarte. La tarte est encore à l’étude.'],
  'azure-cavern': ['Пещера настолько синяя, что эхо отвечает с акцентом.', 'A cave so blue that the echo answers with an accent.', 'מערה כחולה כל כך שההד עונה במבטא.', 'Una cueva tan azul que el eco responde con acento.', 'Une grotte si bleue que l’écho répond avec un accent.'],
  'coastal-road': ['Дорога вдоль берега. Навигатор уверен, что это короткий путь.', 'A road along the coast. The navigator insists it is a shortcut.', 'כביש לאורך החוף. הנווט בטוח שזה קיצור דרך.', 'Una carretera junto a la costa. El navegador insiste en que es un atajo.', 'Une route le long de la côte. Le navigateur assure que c’est un raccourci.'],
  'sunlit-boats': ['Лодки загорают. Капитаны делают вид, что работают.', 'The boats are sunbathing. The captains pretend to work.', 'הסירות משתזפות. הקברניטים מעמידים פנים שהם עובדים.', 'Las barcas toman el sol. Los capitanes fingen que trabajan.', 'Les barques bronzent. Les capitaines font semblant de travailler.'],
  'copper-horizon': ['Горизонт цвета старой монеты. Сдачи не будет.', 'A horizon the colour of an old coin. No change given.', 'אופק בצבע מטבע ישן. אין עודף.', 'Un horizonte del color de una moneda vieja. No se da cambio.', 'Un horizon couleur de vieille pièce. On ne rend pas la monnaie.'],
  'asteroid-red-orbit': ['Астероид на красной орбите. Тормозить не собирается.', 'An asteroid on a red orbit. It has no plans to brake.', 'אסטרואיד במסלול אדום. אין לו כוונה לבלום.', 'Un asteroide en una órbita roja. No piensa frenar.', 'Un astéroïde sur une orbite rouge. Il n’a pas l’intention de freiner.'],
  'golden-forest-pool': ['Лесной бассейн с золотой водой. Купаться можно, выплывать — по записи.', 'A forest pool of golden water. Swimming allowed, getting out by appointment.', 'בריכת יער של מים זהובים. מותר לשחות, לצאת — בתיאום מראש.', 'Un estanque en el bosque con agua dorada. Bañarse está permitido; salir, con cita previa.', 'Un bassin forestier aux eaux dorées. Baignade autorisée, sortie sur rendez-vous.'],
  'lightkeeper-portrait': ['Хранитель света. Выключатель у него в кармане, и он им гордится.', 'The keeper of light. He carries the switch in his pocket and is proud of it.', 'שומר האור. המתג בכיס שלו, והוא גאה בזה.', 'El guardián de la luz. Lleva el interruptor en el bolsillo y está orgulloso de ello.', 'Le gardien de la lumière. Il garde l’interrupteur dans sa poche et en est fier.'],
  'accretion-ring-study': ['Световое кольцо вокруг чёрной дыры. Фотографировать с безопасного расстояния — лет двести.', 'A ring of light around a black hole. Photograph from a safe distance — about two hundred years.', 'טבעת אור סביב חור שחור. לצלם ממרחק בטוח — כמאתיים שנה.', 'Un anillo de luz alrededor de un agujero negro. Fotografiar desde una distancia segura — unos doscientos años.', 'Un anneau de lumière autour d’un trou noir. Photographier à distance de sécurité — environ deux cents ans.'],
  'winter-gate-character': ['Персонаж у зимних ворот ждёт весну. Весна опаздывает уже третий сезон.', 'A character at the winter gate waits for spring. Spring is three seasons late.', 'דמות בשער החורף מחכה לאביב. האביב מאחר כבר שלוש עונות.', 'Un personaje ante la puerta del invierno espera la primavera. La primavera ya lleva tres estaciones de retraso.', 'Un personnage à la porte de l’hiver attend le printemps. Le printemps a déjà trois saisons de retard.'],
  'sky-aperture': ['Небо прищурилось. Выдержка — одна вечность.', 'The sky squints. Exposure time: one eternity.', 'השמיים מצמצמים עיניים. זמן חשיפה: נצח אחד.', 'El cielo entorna los ojos. Tiempo de exposición: una eternidad.', 'Le ciel plisse les yeux. Temps de pose : une éternité.'],
  'supercar-study': ['Автомобиль, который быстрее собственной тени. Тень подала жалобу.', 'A car faster than its own shadow. The shadow has filed a complaint.', 'מכונית מהירה מהצל של עצמה. הצל הגיש תלונה.', 'Un coche más rápido que su propia sombra. La sombra ha presentado una queja.', 'Une voiture plus rapide que sa propre ombre. L’ombre a porté plainte.'],
  'tent-overlook': ['Вид из палатки экспедиции. Будильник — восход, кофе — по желанию звёзд.', 'The view from an expedition tent. Alarm clock: sunrise; coffee: up to the stars.', 'הנוף מאוהל המשלחת. שעון מעורר — הזריחה, קפה — לפי רצון הכוכבים.', 'La vista desde una tienda de expedición. Despertador: el amanecer; café: según digan las estrellas.', 'La vue depuis une tente d’expédition. Réveil : le lever du soleil ; café : selon le bon vouloir des étoiles.'],
  'orbital-city': ['Город на орбите. Пробки бывают только гравитационные.', 'A city in orbit. The only traffic jams are gravitational.', 'עיר במסלול. הפקקים כאן רק כבידתיים.', 'Una ciudad en órbita. Los únicos atascos son gravitacionales.', 'Une ville en orbite. Les seuls embouteillages sont gravitationnels.'],
  'garden-bowl': ['Зелёный натюрморт. Овощи позируют, но морковь просит другой ракурс.', 'A green still life. The vegetables pose; the carrot wants another angle.', 'טבע דומם ירוק. הירקות מצטלמים, הגזר מבקש זווית אחרת.', 'Un bodegón verde. Las verduras posan, pero la zanahoria pide otro ángulo.', 'Une nature morte verte. Les légumes posent, mais la carotte réclame un autre angle.'],
  'violet-observatory': ['Фиолетовая обсерватория. Звёзды здесь видны даже днём — из вежливости.', 'A violet observatory. The stars show up even by day, out of politeness.', 'מצפה סגול. הכוכבים נראים כאן גם ביום — מתוך נימוס.', 'Un observatorio violeta. Aquí las estrellas se ven incluso de día, por cortesía.', 'Un observatoire violet. Ici, les étoiles se montrent même le jour, par politesse.'],
  'arrival-in-the-field': ['Прибытие в поле. Местные коровы делают вид, что ничего не заметили.', 'Arrival in the field. The local cows pretend they noticed nothing.', 'נחיתה בשדה. הפרות המקומיות מעמידות פנים שלא ראו כלום.', 'Llegada al campo. Las vacas del lugar fingen no haber visto nada.', 'Arrivée dans le champ. Les vaches du coin font semblant de n’avoir rien remarqué.'],
  'neural-star': ['Звезда, которая думает. Иногда о нас, но редко.', 'A star that thinks. Sometimes about us, but rarely.', 'כוכב שחושב. לפעמים עלינו, אבל לעיתים רחוקות.', 'Una estrella que piensa. A veces en nosotros, pero pocas.', 'Une étoile qui pense. Parfois à nous, mais rarement.'],
  'umbrella-storm': ['Зонт против грозы: счёт пока ничейный.', 'Umbrella versus storm: the score is still a draw.', 'מטרייה מול סערה: התוצאה עדיין תיקו.', 'Paraguas contra tormenta: de momento, empate.', 'Parapluie contre orage : pour l’instant, match nul.'],
  'levitating-grove': ['Роща, которая устала стоять и решила парить.', 'A grove that got tired of standing and decided to hover.', 'חורשה שהתעייפה לעמוד והחליטה לרחף.', 'Una arboleda que se cansó de estar de pie y decidió flotar.', 'Un bosquet fatigué d’être debout, qui a décidé de flotter.'],
  'cat-and-fish': ['Начальник рыбного отдела проводит инвентаризацию. Недостача ожидается.', 'The head of the fish department is doing an inventory. A shortage is expected.', 'מנהל מחלקת הדגים עורך ספירת מלאי. צפוי חוסר.', 'El jefe del departamento de pescado hace inventario. Se espera un faltante.', 'Le chef du rayon poisson fait l’inventaire. Une pénurie est à prévoir.'],
  'scarlet-disk-city': ['Алый диск над городом. Жители решили, что это реклама.', 'A scarlet disc above the city. Residents decided it was an advert.', 'דיסקה ארגמנית מעל העיר. התושבים החליטו שזו פרסומת.', 'Un disco escarlata sobre la ciudad. Los vecinos decidieron que era publicidad.', 'Un disque écarlate au-dessus de la ville. Les habitants ont décidé que c’était de la pub.'],
  'mountain-house': ['Дом у горного хребта. Соседи — облака, шумят редко.', 'A house by the ridge. The neighbours are clouds and rarely noisy.', 'בית ליד רכס ההרים. השכנים הם עננים, ורק לעיתים רחוקות רועשים.', 'Una casa junto a la cordillera. Los vecinos son nubes y rara vez hacen ruido.', 'Une maison au pied de la crête. Les voisins sont des nuages, rarement bruyants.'],
  'alpine-dawn': ['Тихие вершины. Здесь даже ветер говорит шёпотом.', 'Quiet peaks. Even the wind whispers here.', 'פסגות שקטות. אפילו הרוח לוחשת כאן.', 'Cumbres tranquilas. Aquí hasta el viento habla en susurros.', 'Sommets paisibles. Ici, même le vent chuchote.'],
  'island-house': ['Дом у воды. Почту приносит прилив, ответ — отлив.', 'A house by the water. The tide brings the post, the ebb takes the reply.', 'בית ליד המים. הגאות מביאה את הדואר, השפל לוקח את התשובה.', 'Una casa junto al agua. La marea alta trae el correo; la baja se lleva la respuesta.', 'Une maison au bord de l’eau. La marée haute apporte le courrier, la marée basse emporte la réponse.'],
  'breakfast-at-altitude': ['Завтрак на высоте. Яичницу держим крепко — ветер голоден.', 'Breakfast at altitude. Hold the omelette tight — the wind is hungry.', 'ארוחת בוקר בגובה. מחזיקים חזק את החביתה — הרוח רעבה.', 'Desayuno en las alturas. Sujeta fuerte los huevos fritos — el viento tiene hambre.', 'Petit-déjeuner en altitude. Tenez bien l’omelette — le vent a faim.'],
  'storm-over-valley': ['Гроза над долиной. Молния позирует, гром стесняется.', 'A storm over the valley. Lightning poses, thunder is shy.', 'סערה מעל העמק. הברק מצטלם, הרעם מתבייש.', 'Tormenta sobre el valle. El rayo posa; el trueno se pone tímido.', 'Orage sur la vallée. L’éclair prend la pose, le tonnerre est timide.'],
  'drifting-suit': ['Скафандр в дрейфе. Владелец обещал вернуться к обеду.', 'A spacesuit adrift. Its owner promised to be back for lunch.', 'חליפת חלל נסחפת. הבעלים הבטיח לחזור לארוחת הצהריים.', 'Un traje espacial a la deriva. Su dueño prometió volver para la comida.', 'Un scaphandre à la dérive. Son propriétaire a promis d’être rentré pour le déjeuner.'],
  'lunar-lightburst': ['Луна вспыхнула. Говорят, кто-то включил её не тем выключателем.', 'The Moon flared. Someone pressed the wrong switch, they say.', 'הירח הבזיק. אומרים שמישהו לחץ על המתג הלא נכון.', 'La Luna se encendió de golpe. Dicen que alguien pulsó el interruptor equivocado.', 'La Lune s’est embrasée. On dit que quelqu’un a appuyé sur le mauvais interrupteur.'],
  'crescent-ridge': ['Серп луны зацепился за хребет. Снимаем, пока не отцепился.', 'The crescent Moon has snagged on the ridge. Shoot before it gets loose.', 'חרמש הירח נתקע על הרכס. מצלמים לפני שישתחרר.', 'La media luna se ha enganchado en la cresta. Hay que disparar antes de que se suelte.', 'Le croissant de lune s’est accroché à la crête. On déclenche avant qu’il se décroche.'],
  'eye-collage-study': ['Исследование взгляда. Кажется, он смотрит на вас дольше, чем вы на него.', 'A study of a gaze. It seems to look at you longer than you look at it.', 'מחקר של מבט. נראה שהוא מסתכל עליכם יותר זמן משאתם עליו.', 'Estudio de una mirada. Parece que te mira más tiempo del que tú la miras.', 'Étude d’un regard. On dirait qu’il vous regarde plus longtemps que vous ne le regardez.'],
  'rose-interior': ['Розовая каюта. Иллюминатор тоже хотел бы быть розовым, но не прошёл кастинг.', 'A pink cabin. The porthole wanted to be pink too but failed the casting.', 'תא ורוד. גם הצוהר רצה להיות ורוד, אבל לא עבר את האודישן.', 'Un camarote rosa. El ojo de buey también quería ser rosa, pero no pasó el casting.', 'Une cabine rose. Le hublot voulait être rose lui aussi, mais il a raté le casting.'],
  'lake-ducks': ['Два навигатора. Оба уверены, что ведут именно они.', 'Two navigators. Each is sure that they are the one leading.', 'שני נווטים. כל אחד בטוח שהוא זה שמוביל.', 'Dos navegantes. Cada uno está seguro de que es él quien guía.', 'Deux navigateurs. Chacun est sûr que c’est lui qui mène.'],
  'silhouette-spectrum': ['Силуэт разложили на спектр. Собрать обратно пока не удалось.', 'A silhouette split into a spectrum. Nobody has managed to put it back together.', 'צללית פורקה לספקטרום. עדיין לא הצליחו להרכיב אותה בחזרה.', 'Una silueta descompuesta en un espectro. Nadie ha logrado volver a montarla.', 'Une silhouette décomposée en spectre. Personne n’a encore réussi à la recomposer.'],
  'basketball-net-study': ['Геометрия сетки. Мяч пролетел мимо, но композиция — в корзину.', 'The geometry of a net. The ball missed, but the composition scored.', 'הגאומטריה של רשת. הכדור פספס, אבל הקומפוזיציה קלעה.', 'La geometría de una red. El balón falló, pero la composición encestó.', 'La géométrie d’un filet. Le ballon a raté, mais la composition a marqué.'],
  'breakfast-composition': ['Завтрак как композиция. Съесть его — значит испортить кадр.', 'Breakfast as a composition. Eating it would ruin the shot.', 'ארוחת בוקר כקומפוזיציה. לאכול אותה — להרוס את הפריים.', 'El desayuno como composición. Comérselo arruinaría la foto.', 'Le petit-déjeuner comme composition. Le manger gâcherait la photo.'],
  'blue-flower-study': ['Синий ботанический этюд. Цветок утверждает, что он в фокусе по собственному желанию.', 'A blue botanical study. The flower claims it is in focus of its own free will.', 'מחקר בוטני כחול. הפרח טוען שהוא בפוקוס מרצונו החופשי.', 'Un estudio botánico en azul. La flor asegura que está enfocada por voluntad propia.', 'Une étude botanique bleue. La fleur affirme être nette de son plein gré.'],
  'solar-botanist': ['Солнечный ботаник поливает растения светом. Счёт за электричество — астрономический.', 'The solar botanist waters plants with light. The power bill is astronomical.', 'הבוטנאי הסולארי משקה צמחים באור. חשבון החשמל אסטרונומי.', 'El botánico solar riega las plantas con luz. La factura de la luz es astronómica.', 'Le botaniste solaire arrose les plantes avec de la lumière. La facture d’électricité est astronomique.'],
  'crimson-signal': ['Багровый сигнал. Расшифровка: «Мы ничего не поняли, но нам понравилось».', 'A crimson signal. Decoded: “We understood nothing, but we liked it.”', 'אות ארגמני. פענוח: „לא הבנו כלום, אבל אהבנו”.', 'Una señal carmesí. Descifrada: «No entendimos nada, pero nos gustó».', 'Un signal cramoisi. Décodé : « Nous n’avons rien compris, mais ça nous a plu. »'],
  'waterlily-depths': ['Под поверхностью. Кувшинки знают больше, чем говорят.', 'Beneath the surface. The water lilies know more than they say.', 'מתחת לפני המים. החבצלות יודעות יותר ממה שהן אומרות.', 'Bajo la superficie. Los nenúfares saben más de lo que dicen.', 'Sous la surface. Les nénuphars en savent plus qu’ils ne le disent.'],
  'autumn-hills': ['Сезон медного света. Холмы покрылись ржавчиной — красивой.', 'The season of copper light. The hills have rusted — beautifully.', 'עונת האור הנחושתי. הגבעות החלידו — ביופי.', 'La temporada de luz cobriza. Las colinas se han oxidado — con mucho estilo.', 'La saison de la lumière cuivrée. Les collines ont rouillé — joliment.'],
  'mossy-forest': ['Лесная обсерватория. Телескоп заменили мхом — видно не хуже.', 'A forest observatory. The telescope was replaced with moss — the view is no worse.', 'מצפה יער. את הטלסקופ החליפו בטחב — רואים לא פחות טוב.', 'Un observatorio forestal. Cambiaron el telescopio por musgo — y se ve igual de bien.', 'Un observatoire forestier. Le télescope a été remplacé par de la mousse — on n’y voit pas plus mal.'],
  'starship-design-study': ['Проект межзвёздного судна. Чертёж утверждён, бюджет — в другой галактике.', 'A starship design. The drawing is approved; the budget is in another galaxy.', 'תכנון ספינה בין־כוכבית. השרטוט אושר, התקציב — בגלקסיה אחרת.', 'El diseño de una nave estelar. El plano está aprobado; el presupuesto, en otra galaxia.', 'Le projet d’un vaisseau stellaire. Le plan est validé ; le budget est dans une autre galaxie.'],
  'chromatic-pilot': ['Хроматический пилот. Летает только по радуге, на остальных трассах скучно.', 'A chromatic pilot. Flies only along rainbows — the other routes are boring.', 'טייס כרומטי. טס רק לאורך קשתות — שאר המסלולים משעממים.', 'Un piloto cromático. Solo vuela por los arcoíris — las demás rutas son aburridas.', 'Un pilote chromatique. Il ne vole que le long des arcs-en-ciel — les autres routes sont ennuyeuses.'],
  'sunlight-hills': ['Свет над холмами. Солнце задержалось, чтобы попасть в кадр.', 'Light over the hills. The sun lingered to get into the shot.', 'אור מעל הגבעות. השמש התעכבה כדי להיכנס לפריים.', 'Luz sobre las colinas. El sol se quedó un rato más para salir en la foto.', 'Lumière sur les collines. Le soleil s’est attardé pour être dans le cadre.'],
  'mountain-room': ['Комната над облаками. Окно открывать не рекомендуется: облака заходят без стука.', 'A room above the clouds. Keep the window shut: clouds come in without knocking.', 'חדר מעל העננים. לא מומלץ לפתוח חלון: העננים נכנסים בלי לדפוק.', 'Una habitación sobre las nubes. Mantén la ventana cerrada: las nubes entran sin llamar.', 'Une chambre au-dessus des nuages. Gardez la fenêtre fermée : les nuages entrent sans frapper.'],
  'still-life-tea': ['Чайный натюрморт. Чай остыл, пока художник выбирал свет.', 'A tea still life. The tea went cold while the artist chose the light.', 'טבע דומם עם תה. התה התקרר בזמן שהאמן בחר את האור.', 'Un bodegón con té. El té se enfrió mientras el artista elegía la luz.', 'Une nature morte au thé. Le thé a refroidi pendant que l’artiste choisissait la lumière.'],
  'chorus-of-travelers': ['Хор путешественников. Поют в унисон, спорят о маршруте вразнобой.', 'A chorus of travellers. They sing in unison and argue about the route out of tune.', 'מקהלת מטיילים. שרים ביחד, מתווכחים על המסלול בזיופים.', 'Un coro de viajeros. Cantan al unísono y discuten la ruta desafinando.', 'Un chœur de voyageurs. Ils chantent à l’unisson et se disputent sur l’itinéraire en cacophonie.'],
  'cat-through-glass': ['Кот сквозь стекло. Стекло, по мнению кота, — временное недоразумение.', 'A cat through glass. In the cat’s opinion, glass is a temporary misunderstanding.', 'חתול מבעד לזכוכית. לדעת החתול, הזכוכית היא אי־הבנה זמנית.', 'Un gato tras el cristal. Según el gato, el cristal es un malentendido temporal.', 'Un chat derrière la vitre. Selon le chat, la vitre est un malentendu passager.'],
  'autumn-leaf': ['Осенний лист. Последний на ветке и очень этим гордится.', 'An autumn leaf. The last one on the branch and very proud of it.', 'עלה סתיו. האחרון על הענף וגאה בזה מאוד.', 'Una hoja de otoño. La última de la rama, y muy orgullosa de ello.', 'Une feuille d’automne. La dernière sur la branche, et très fière de l’être.'],
  'kitchen-story': ['История на кухне. Сюжет закручен, суп — тоже.', 'A story in the kitchen. The plot thickens, and so does the soup.', 'סיפור במטבח. העלילה מסתבכת, וגם המרק.', 'Una historia en la cocina. La trama se espesa, y la sopa también.', 'Une histoire en cuisine. L’intrigue s’épaissit, la soupe aussi.'],
  'abstract-botanical': ['Ботаническая абстракция. Растение уверено, что его нарисовали правильно.', 'A botanical abstraction. The plant is sure it was drawn correctly.', 'הפשטה בוטנית. הצמח בטוח שציירו אותו נכון.', 'Una abstracción botánica. La planta está segura de que la dibujaron bien.', 'Une abstraction botanique. La plante est sûre d’avoir été dessinée correctement.'],
  'cosmic-evening-reader': ['Читатель на краю вечера. Дочитает главу — и наступит ночь.', 'A reader at the edge of evening. One more chapter and night will fall.', 'קורא בקצה הערב. עוד פרק אחד — ותרד הלילה.', 'Un lector al borde de la tarde. Un capítulo más y caerá la noche.', 'Un lecteur au bord du soir. Encore un chapitre, et la nuit tombera.'],
  'red-eye-over-snow': ['Красный глаз над снегом. Снег делает вид, что не замечает.', 'A red eye over the snow. The snow pretends not to notice.', 'עין אדומה מעל השלג. השלג מעמיד פנים שלא שם לב.', 'Un ojo rojo sobre la nieve. La nieve finge no darse cuenta.', 'Un œil rouge au-dessus de la neige. La neige fait semblant de ne rien remarquer.'],
  'pink-family-study': ['Семейный этюд в розовом. Все улыбаются, кроме фотографа — он считает экспозицию.', 'A family study in pink. Everyone smiles except the photographer, busy with exposure.', 'מחקר משפחתי בוורוד. כולם מחייכים חוץ מהצלם — הוא מחשב חשיפה.', 'Un estudio familiar en rosa. Todos sonríen menos el fotógrafo, ocupado con la exposición.', 'Une étude familiale en rose. Tout le monde sourit, sauf le photographe, occupé par l’exposition.'],
  'rippled-sky-road': ['Дорога под волнистым небом. Небо укачивает, дорога держится.', 'A road under a rippled sky. The sky makes you seasick; the road holds on.', 'כביש מתחת לשמיים גליים. השמיים עושים בחילה, הכביש מחזיק מעמד.', 'Una carretera bajo un cielo ondulado. El cielo marea; la carretera aguanta.', 'Une route sous un ciel ondulé. Le ciel donne le mal de mer ; la route tient bon.'],
  'painted-world': ['Расписной мир. Краска ещё не высохла — не трогать горизонт.', 'A painted world. The paint is still wet — do not touch the horizon.', 'עולם מצויר. הצבע עוד לא יבש — לא לגעת באופק.', 'Un mundo pintado. La pintura aún está fresca — no toques el horizonte.', 'Un monde peint. La peinture est encore fraîche — ne touchez pas à l’horizon.'],
  'orbital-dawn': ['Орбитальный рассвет. Шестнадцатый за сегодня, и всё равно красиво.', 'An orbital dawn. The sixteenth today, and still beautiful.', 'זריחה במסלול. השש־עשרה היום, ועדיין יפה.', 'Un amanecer orbital. El decimosexto de hoy, y sigue siendo precioso.', 'Une aube orbitale. La seizième de la journée, et toujours aussi belle.'],
  'nebula-fingers': ['Пальцы туманности тянутся к соседней галактике. Наверное, за солью.', 'The fingers of a nebula reach for the next galaxy. Probably for the salt.', 'אצבעות הערפילית נשלחות לגלקסיה השכנה. כנראה בשביל המלח.', 'Los dedos de una nebulosa se estiran hacia la galaxia vecina. Seguramente para alcanzar la sal.', 'Les doigts d’une nébuleuse se tendent vers la galaxie voisine. Sans doute pour attraper le sel.'],
  'copper-canyon': ['Медный каньон. Эхо здесь звенит, как мелочь в кармане.', 'A copper canyon. The echo jingles like change in a pocket.', 'קניון נחושת. ההד מצלצל כמו מטבעות בכיס.', 'Un cañón de cobre. El eco tintinea como las monedas sueltas en un bolsillo.', 'Un canyon cuivré. L’écho tinte comme de la petite monnaie dans une poche.'],
  'lunar-module-study': ['Лунный модуль в разрезе. Самое интересное — где спрятан чайник.', 'A cutaway lunar module. The most interesting part is where the kettle is hidden.', 'רכב ירח בחתך. הכי מעניין — איפה הוסתר הקומקום.', 'Un módulo lunar en corte. Lo más interesante: dónde esconden el hervidor.', 'Un module lunaire en coupe. Le plus intéressant : l’endroit où se cache la bouilloire.'],
  'spiral-ember': ['Спиральный уголёк. Галактика, которую забыли потушить.', 'A spiral ember. A galaxy someone forgot to put out.', 'גחלת ספירלית. גלקסיה שמישהו שכח לכבות.', 'Una brasa en espiral. Una galaxia que alguien olvidó apagar.', 'Une braise en spirale. Une galaxie que quelqu’un a oublié d’éteindre.'],
  'eclipse-over-city': ['Затмение над городом. Фонари включились и смутились.', 'An eclipse over the city. The street lamps switched on and felt awkward.', 'ליקוי מעל העיר. הפנסים נדלקו והתביישו.', 'Un eclipse sobre la ciudad. Las farolas se encendieron y se ruborizaron.', 'Une éclipse sur la ville. Les réverbères se sont allumés, puis ont rougi.'],
  'valley-of-mist': ['Долина тумана. Тропинку видно только тем, кто уже знает дорогу.', 'The valley of mist. The path is visible only to those who already know the way.', 'עמק הערפל. השביל נראה רק למי שכבר מכיר את הדרך.', 'El valle de la niebla. El sendero solo lo ven quienes ya conocen el camino.', 'La vallée de la brume. Le sentier n’est visible que pour ceux qui connaissent déjà le chemin.'],
  'desert-in-bloom': ['Пустыня передумала и расцвела. Кактусы в шоке.', 'The desert changed its mind and bloomed. The cacti are in shock.', 'המדבר שינה את דעתו ופרח. הקקטוסים בהלם.', 'El desierto cambió de opinión y floreció. Los cactus están en shock.', 'Le désert a changé d’avis et a fleuri. Les cactus sont sous le choc.'],
  'lightning-column': ['Грозовая колонна. Держит небо, пока облака отдыхают.', 'A lightning column. It holds up the sky while the clouds take a break.', 'עמוד ברקים. מחזיק את השמיים בזמן שהעננים נחים.', 'Una columna de rayos. Sostiene el cielo mientras las nubes descansan.', 'Une colonne d’orage. Elle soutient le ciel pendant que les nuages font une pause.'],
  'ember-cloud': ['Облако цвета угля. Внутри, похоже, кто-то жарит шашлык.', 'A cloud the colour of coal. Someone inside seems to be having a barbecue.', 'ענן בצבע פחם. נראה שמישהו בפנים עושה על האש.', 'Una nube del color del carbón. Parece que dentro alguien está haciendo una barbacoa.', 'Un nuage couleur charbon. On dirait que quelqu’un y fait un barbecue.'],
  'night-from-orbit': ['Ночь с орбиты. Города светятся, как забытые зарядки.', 'Night from orbit. The cities glow like forgotten chargers.', 'לילה מהמסלול. הערים זוהרות כמו מטענים שנשכחו בשקע.', 'La noche vista desde la órbita. Las ciudades brillan como cargadores olvidados.', 'La nuit vue de l’orbite. Les villes brillent comme des chargeurs oubliés.'],
  'retro-lunar-port': ['Ретролунный порт. Рейсы задерживаются с 1962 года.', 'A retro lunar port. Flights have been delayed since 1962.', 'נמל ירח רטרו. הטיסות מתעכבות מאז 1962.', 'Un puerto lunar retro. Los vuelos llevan retraso desde 1962.', 'Un port lunaire rétro. Les vols sont retardés depuis 1962.'],
  'orbital-window-seat': ['Место у окна на орбите. Самое дорогое кресло — из-за вида на Землю.', 'A window seat in orbit. The priciest chair, thanks to the view of Earth.', 'מושב ליד החלון במסלול. הכיסא היקר ביותר — בגלל הנוף לכדור הארץ.', 'Un asiento de ventanilla en órbita. El más caro, por las vistas a la Tierra.', 'Une place côté hublot en orbite. Le siège le plus cher, pour la vue sur la Terre.'],
  'retro-free-flight': ['Ретрополёт без билета. Контролёр догоняет на реактивном ранце.', 'A retro flight without a ticket. The inspector is catching up on a jetpack.', 'טיסת רטרו בלי כרטיס. הפקח משיג על תרמיל סילון.', 'Un vuelo retro sin billete. El revisor lo persigue con una mochila propulsora.', 'Un vol rétro sans billet. Le contrôleur le rattrape en jetpack.'],
  'frontier-pilot': ['Пилот фронтира. Сажает корабль куда угодно, иногда даже на посадочную полосу.', 'A frontier pilot. Lands anywhere, occasionally even on the runway.', 'טייסת גבול. נוחתת בכל מקום, לפעמים אפילו על המסלול.', 'Piloto de la frontera. Aterriza en cualquier sitio; de vez en cuando, incluso en la pista.', 'Pilote des confins. Atterrit n’importe où, parfois même sur la piste.'],
  'copper-flight-jacket': ['Медная лётная куртка. Пережила три посадки и одну стирку.', 'A copper flight jacket. It survived three landings and one wash.', 'מעיל טיסה נחושתי. שרד שלוש נחיתות וכביסה אחת.', 'Una chaqueta de vuelo cobriza. Sobrevivió a tres aterrizajes y a un lavado.', 'Un blouson d’aviateur cuivré. Il a survécu à trois atterrissages et à un lavage.'],
  'silver-traveler': ['Серебряная путешественница. Отражает солнце, комплименты и метеориты.', 'A silver traveller. Reflects sunlight, compliments and meteorites.', 'מטיילת כסופה. מחזירה אור שמש, מחמאות ומטאוריטים.', 'Una viajera plateada. Refleja el sol, los cumplidos y los meteoritos.', 'Une voyageuse argentée. Elle renvoie le soleil, les compliments et les météorites.'],
  'lunar-resort': ['Курорт без приливов. Зато песок здесь никогда не мокрый.', 'A resort without tides. On the bright side, the sand is never wet.', 'אתר נופש בלי גאות. לפחות החול אף פעם לא רטוב.', 'Un balneario sin mareas. Eso sí, la arena nunca está mojada.', 'Une station balnéaire sans marées. En revanche, le sable n’est jamais mouillé.'],
  'first-contact-seminar': ['Семинар первого контакта. Тема: «Как не помахать не той рукой».', 'A first-contact seminar. Topic: “How not to wave the wrong hand.”', 'סמינר מגע ראשון. נושא: „איך לא לנופף ביד הלא נכונה”.', 'Un seminario de primer contacto. Tema: «Cómo no saludar con la mano equivocada».', 'Un séminaire de premier contact. Thème : « Comment ne pas saluer de la mauvaise main ».'],
  'portal-camera-bear': ['Медведь у съёмочной площадки. Требует гонорар мёдом.', 'A bear on the film set. Demands to be paid in honey.', 'דוב בסט הצילומים. דורש שכר בדבש.', 'Un oso en el plató. Exige cobrar en miel.', 'Un ours sur le plateau de tournage. Il exige d’être payé en miel.'],
  'saturn-landing': ['Посадка у Сатурна. Парковаться на кольцах строго запрещено.', 'Landing at Saturn. Parking on the rings is strictly forbidden.', 'נחיתה ליד שבתאי. חנייה על הטבעות אסורה בהחלט.', 'Aterrizaje junto a Saturno. Está terminantemente prohibido aparcar en los anillos.', 'Atterrissage près de Saturne. Stationnement strictement interdit sur les anneaux.'],
  'two-travelers': ['Два путешественника. Один несёт карту, другой — уверенность.', 'Two travellers. One carries the map, the other carries confidence.', 'שני מטיילים. אחד נושא מפה, השני — ביטחון.', 'Dos viajeros. Uno lleva el mapa; el otro, la seguridad.', 'Deux voyageurs. L’un porte la carte, l’autre l’assurance.'],
  'matter-transmission': ['Передача материи. Доставлено всё, кроме левого носка.', 'Matter transmission. Everything arrived except the left sock.', 'שידור חומר. הכול הגיע חוץ מהגרב השמאלית.', 'Transmisión de materia. Llegó todo menos el calcetín izquierdo.', 'Transmission de matière. Tout est arrivé, sauf la chaussette gauche.'],
  'star-grazers': ['Пастухи звёзд. Стадо разбрелось по всему небу.', 'Star herders. The flock has wandered all over the sky.', 'רועי כוכבים. העדר התפזר על כל השמיים.', 'Pastores de estrellas. El rebaño se ha dispersado por todo el cielo.', 'Bergers d’étoiles. Le troupeau s’est dispersé dans tout le ciel.'],
  'stellar-engineer': ['Звёздный механик. Всё, что не починила, называет инсталляцией.', 'A stellar engineer. Whatever she cannot fix, she calls an installation.', 'מכונאית כוכבים. כל מה שלא תיקנה היא קוראת לו מיצב.', 'Una ingeniera estelar. Todo lo que no logra reparar lo llama instalación.', 'Une ingénieure stellaire. Tout ce qu’elle ne répare pas, elle l’appelle une installation.'],
  'orbital-botanist': ['Ботаник на орбите. Растения растут во все стороны, потому что «вверх» нет.', 'A botanist in orbit. The plants grow every way, since there is no “up”.', 'בוטנאי במסלול. הצמחים גדלים לכל הכיוונים, כי אין „למעלה”.', 'Un botánico en órbita. Las plantas crecen en todas direcciones, porque no hay «arriba».', 'Un botaniste en orbite. Les plantes poussent dans tous les sens, puisqu’il n’y a pas de « haut ».'],
  'galaxy-after-sunset': ['Галактика после заката. Вышла на смену, когда солнце ушло домой.', 'A galaxy after sunset. It started its shift when the sun went home.', 'גלקסיה אחרי השקיעה. התחילה משמרת כשהשמש הלכה הביתה.', 'Una galaxia tras la puesta de sol. Empezó su turno cuando el sol se fue a casa.', 'Une galaxie après le coucher du soleil. Elle a pris son service quand le soleil est rentré chez lui.'],
  'retro-bridge-pilot': ['Пилот ретромостика. Кнопок больше, чем звёзд, и половина подписана карандашом.', 'A retro bridge pilot. More buttons than stars, half of them labelled in pencil.', 'טייסת בגשר רטרו. יותר כפתורים מכוכבים, וחצי מהם מסומנים בעיפרון.', 'Un piloto de puente retro. Más botones que estrellas, la mitad etiquetados a lápiz.', 'Un pilote de passerelle rétro. Plus de boutons que d’étoiles, dont la moitié étiquetés au crayon.'],
  'atomic-comic-study': ['Атомный комикс. Пузыри с репликами на всякий случай заземлены.', 'An atomic comic. The speech bubbles are earthed, just in case.', 'קומיקס אטומי. בועות הדיבור מוארקות, ליתר ביטחון.', 'Un cómic atómico. Los bocadillos tienen toma de tierra, por si acaso.', 'Une BD atomique. Les bulles sont reliées à la terre, au cas où.'],
  'orbital-diner': ['Орбитальная закусочная. Кофе подают в пакетах, пончики — по траектории.', 'An orbital diner. Coffee comes in pouches, doughnuts on a trajectory.', 'דיינר במסלול. הקפה מוגש בשקיות, הסופגניות — במסלול מעופף.', 'Una cafetería orbital. El café se sirve en bolsitas; los dónuts, en trayectoria.', 'Un snack orbital. Le café est servi en sachets, les beignets en trajectoire.'],
  'goggle-inventor': ['Изобретательница в очках. Очки сама и изобрела — после третьего взрыва.', 'An inventor in goggles. She invented the goggles herself, after the third explosion.', 'ממציאה במשקפי מגן. את המשקפיים המציאה בעצמה — אחרי הפיצוץ השלישי.', 'Una inventora con gafas protectoras. Las inventó ella misma, después de la tercera explosión.', 'Une inventrice à lunettes de protection. Elle a inventé les lunettes elle-même, après la troisième explosion.'],
  'helmet-skull-study': ['Шлем помнит всё. Особенно того, кто забыл его застегнуть.', 'The helmet remembers everything. Especially whoever forgot to fasten it.', 'הקסדה זוכרת הכול. במיוחד את מי ששכח לסגור אותה.', 'El casco lo recuerda todo. Sobre todo a quien olvidó abrochárselo.', 'Le casque se souvient de tout. Surtout de celui qui a oublié de l’attacher.'],
  'red-void': ['Красная пустота. Пусто, но со вкусом.', 'A red void. Empty, but tasteful.', 'ריק אדום. ריק, אבל בטוב טעם.', 'Un vacío rojo. Vacío, pero con gusto.', 'Un vide rouge. Vide, mais avec goût.'],
  'fire-alchemist': ['Алхимик огня. Кухня у неё огнеупорная, гости — не всегда.', 'A fire alchemist. Her kitchen is fireproof; her guests not always.', 'אלכימאית אש. המטבח שלה חסין אש, האורחים — לא תמיד.', 'Una alquimista del fuego. Su cocina es ignífuga; sus invitados, no siempre.', 'Une alchimiste du feu. Sa cuisine est ignifugée ; ses invités, pas toujours.'],
  'forest-bard': ['Бард лесного фронтира. Песни длинные, костёр короткий.', 'A forest-frontier bard. Long songs, short campfire.', 'פייטנית יער הגבול. שירים ארוכים, מדורה קצרה.', 'Un bardo de la frontera forestal. Canciones largas, hoguera corta.', 'Un barde des confins forestiers. Chansons longues, feu de camp court.'],
  'elder-seer': ['Хранительница знаков. Предсказывает погоду по костям — точнее синоптиков.', 'The keeper of signs. Forecasts the weather from bones — better than the forecasters.', 'שומרת הסימנים. חוזה מזג אוויר לפי עצמות — מדויק יותר מהחזאים.', 'La guardiana de los presagios. Predice el tiempo con huesos — mejor que los meteorólogos.', 'La gardienne des présages. Elle prédit la météo avec des os — mieux que les météorologues.'],
  'forest-keeper': ['Хранительница леса. Грибы на её поляне растут строго по расписанию.', 'The forest keeper. Mushrooms in her glade grow strictly on schedule.', 'שומרת היער. הפטריות בקרחת שלה צומחות לפי לוח זמנים.', 'La guardiana del bosque. Las setas de su claro crecen estrictamente según el horario.', 'La gardienne de la forêt. Dans sa clairière, les champignons poussent strictement selon l’horaire.'],
  'lenticular-volcano': ['Шляпа для вулкана. Облако село идеально — вулкан доволен.', 'A hat for a volcano. The cloud fits perfectly; the volcano is pleased.', 'כובע להר געש. הענן ישב בדיוק — ההר מרוצה.', 'Un sombrero para un volcán. La nube le queda perfecta; el volcán está encantado.', 'Un chapeau pour un volcan. Le nuage lui va parfaitement ; le volcan est ravi.'],
  'dark-library-keeper': ['Библиотекарь сумерек. Просроченные книги возвращаются сами.', 'The twilight librarian. Overdue books return on their own.', 'ספרנית הדמדומים. ספרים באיחור חוזרים מעצמם.', 'El bibliotecario del crepúsculo. Los libros atrasados vuelven solos.', 'Le bibliothécaire du crépuscule. Les livres en retard reviennent tout seuls.'],
  'void-sentinel': ['Страж пустоты. Охраняет ничто, и очень успешно.', 'The sentinel of the void. Guards nothing, very successfully.', 'שומר הריק. שומר על כלום, ובהצלחה רבה.', 'El centinela del vacío. Vigila la nada, y con mucho éxito.', 'La sentinelle du vide. Elle garde le néant, avec beaucoup de succès.'],
  'fungal-skull': ['Грибной советник. Советы даёт медленно, но они прорастают.', 'A fungal adviser. Gives advice slowly, but it takes root.', 'יועץ פטרייתי. נותן עצות לאט, אבל הן משתרשות.', 'Un consejero fúngico. Da consejos despacio, pero echan raíces.', 'Un conseiller fongique. Il donne ses conseils lentement, mais ils prennent racine.'],
  'lunar-apparition': ['Лунное явление. Явилось без записи, ушло без объяснений.', 'A lunar apparition. Came without an appointment, left without explanation.', 'הופעה ירחית. באה בלי תור, הלכה בלי הסבר.', 'Una aparición lunar. Llegó sin cita y se fue sin explicaciones.', 'Une apparition lunaire. Venue sans rendez-vous, repartie sans explication.'],
  'twin-moon-towers': ['Башни двух лун. Жильцы спорят, какая луна их.', 'Towers of the two moons. The residents argue about which moon is theirs.', 'מגדלי שני הירחים. הדיירים מתווכחים איזה ירח שלהם.', 'Las torres de las dos lunas. Los vecinos discuten cuál de las lunas es la suya.', 'Les tours des deux lunes. Les habitants se disputent pour savoir quelle lune est la leur.'],
  'clockwork-tree': ['Дерево времени. Листья опадают ровно в полночь — и тикают.', 'The tree of time. Its leaves fall exactly at midnight — and tick.', 'עץ הזמן. העלים נושרים בדיוק בחצות — ומתקתקים.', 'El árbol del tiempo. Sus hojas caen justo a medianoche — y hacen tictac.', 'L’arbre du temps. Ses feuilles tombent pile à minuit — et font tic-tac.'],
  'floating-reading-room': ['Комната, забывшая пол. Книги не падают — им интересно.', 'A room that forgot its floor. The books do not fall — they are curious.', 'חדר ששכח את הרצפה. הספרים לא נופלים — מעניין להם.', 'Una habitación que olvidó su suelo. Los libros no caen — sienten curiosidad.', 'Une pièce qui a oublié son sol. Les livres ne tombent pas — ils sont curieux.'],
  'root-thought': ['Мысль пустила корни. Теперь её не выкорчевать.', 'A thought has taken root. Now it cannot be pulled out.', 'מחשבה הכתה שורשים. עכשיו אי אפשר לעקור אותה.', 'Una idea ha echado raíces. Ahora no hay quien la arranque.', 'Une pensée a pris racine. Impossible de l’arracher maintenant.'],
  'observatory-tree': ['Дерево-обсерватория. Белки ведут журнал наблюдений.', 'An observatory tree. The squirrels keep the observation log.', 'עץ־מצפה. הסנאים מנהלים את יומן התצפיות.', 'Un árbol observatorio. Las ardillas llevan el registro de observaciones.', 'Un arbre-observatoire. Les écureuils tiennent le journal d’observation.'],
  'galactic-cliff': ['Скала под галактикой. Край обрыва — лучшее место для селфи и худшее для шага назад.', 'A cliff under the galaxy. The edge is the best spot for a selfie and the worst for a step back.', 'צוק מתחת לגלקסיה. הקצה הוא המקום הטוב לסלפי והגרוע לצעד אחורה.', 'Un acantilado bajo la galaxia. El borde es el mejor sitio para un selfi y el peor para dar un paso atrás.', 'Une falaise sous la galaxie. Le bord est le meilleur endroit pour un selfie, et le pire pour reculer d’un pas.'],
  'crowned-wanderer': ['Коронованный странник. Пережил всё — корону носит по праву.', 'The crowned wanderer. Survived everything and wears the crown by right.', 'הנודד המוכתר. שרד הכול ועונד את הכתר בזכות.', 'El errante coronado. Sobrevivió a todo y lleva la corona por derecho propio.', 'Le vagabond couronné. Il a survécu à tout et porte la couronne de plein droit.'],
  'flying-tree-castle': ['Летающий замок-дерево. Ремонт крыши — только с крыльями.', 'A flying tree castle. Roof repairs strictly with wings.', 'טירת עץ מעופפת. תיקון הגג — רק עם כנפיים.', 'Un castillo-árbol volador. Las reparaciones del tejado, solo con alas.', 'Un château-arbre volant. Réparation du toit uniquement avec des ailes.'],
  'storm-at-horizon': ['Гроза на горизонте. Идёт сюда, но не торопится.', 'A storm on the horizon. It is coming this way, in no hurry.', 'סערה באופק. בדרך לכאן, בלי למהר.', 'Una tormenta en el horizonte. Viene hacia aquí, sin prisa.', 'Un orage à l’horizon. Il arrive par ici, sans se presser.'],
  'volcano-under-stars': ['Вулкан под звёздами. Ночью он светится, днём делает вид, что спит.', 'A volcano under the stars. At night it glows, by day it pretends to sleep.', 'הר געש מתחת לכוכבים. בלילה הוא זוהר, ביום מעמיד פנים שהוא ישן.', 'Un volcán bajo las estrellas. De noche brilla; de día finge dormir.', 'Un volcan sous les étoiles. La nuit, il rougeoie ; le jour, il fait semblant de dormir.'],
  'frontier-freighter': ['Грузовик фронтира. Скрипит, но довозит — и груз, и истории.', 'A frontier freighter. It creaks but delivers — cargo and stories alike.', 'משאית הגבול. חורקת, אבל מגיעה — עם מטען ועם סיפורים.', 'Un carguero de la frontera. Cruje, pero llega — con la carga y con las historias.', 'Un cargo des confins. Il grince, mais il livre — la cargaison comme les histoires.'],
  'silver-orbital-ship': ['Серебряный орбитальщик. Блестит так, что его видно с Земли без телескопа.', 'A silver orbiter. Shines so brightly it can be seen from Earth without a telescope.', 'ספינת מסלול כסופה. מבריקה כל כך שרואים אותה מכדור הארץ בלי טלסקופ.', 'Una nave orbital plateada. Brilla tanto que se ve desde la Tierra sin telescopio.', 'Un orbiteur argenté. Il brille tant qu’on le voit depuis la Terre sans télescope.'],
  'twin-engine-vessel': ['Двухмоторный странник. Если откажет один мотор, второй будет ворчать.', 'A twin-engine wanderer. If one engine fails, the other will grumble.', 'נודד דו־מנועי. אם מנוע אחד יכשל, השני ירטון.', 'Un errante bimotor. Si falla un motor, el otro refunfuñará.', 'Un vagabond bimoteur. Si un moteur lâche, l’autre râlera.'],
  'long-haul-cruiser': ['Крейсер дальних рейсов. В меню — три вида супа и бесконечность.', 'A long-haul cruiser. The menu offers three soups and infinity.', 'סיירת לטיסות ארוכות. בתפריט — שלושה סוגי מרק ואינסוף.', 'Un crucero de largo recorrido. En el menú: tres sopas y el infinito.', 'Un croiseur long-courrier. Au menu : trois soupes et l’infini.'],
  'ring-drive-ship': ['Кольцевой двигатель. Летит по кругу, но всегда вперёд.', 'A ring-drive ship. It flies in circles, yet always forward.', 'ספינה עם הנעת טבעת. טסה במעגלים, אבל תמיד קדימה.', 'Una nave con motor de anillo. Vuela en círculos, pero siempre hacia delante.', 'Un vaisseau à propulsion annulaire. Il vole en rond, mais toujours vers l’avant.'],
  'event-horizon-vessel': ['Корабль у горизонта событий. Экипаж машет на прощание — очень медленно.', 'A ship at the event horizon. The crew waves goodbye — very slowly.', 'ספינה באופק האירועים. הצוות מנופף לשלום — לאט מאוד.', 'Una nave en el horizonte de sucesos. La tripulación dice adiós con la mano — muy despacio.', 'Un vaisseau à l’horizon des événements. L’équipage fait au revoir de la main — très lentement.'],
  'tentacle-engineer': ['Инженер многозадачности. Восемь рук, восемь задач, один перерыв на кофе.', 'An engineer of multitasking. Eight hands, eight tasks, one coffee break.', 'מהנדס ריבוי משימות. שמונה ידיים, שמונה משימות, הפסקת קפה אחת.', 'Un ingeniero multitarea. Ocho manos, ocho tareas, una sola pausa para el café.', 'Un ingénieur du multitâche. Huit mains, huit tâches, une seule pause-café.'],
  'android-city-guide': ['Проводница техногорода. Знает каждый переулок и каждый пароль от Wi-Fi.', 'A techno-city guide. Knows every alley and every Wi-Fi password.', 'מדריכת עיר הטכנולוגיה. מכירה כל סמטה וכל סיסמת Wi-Fi.', 'Una guía de la tecnociudad. Conoce cada callejón y cada contraseña del wifi.', 'Une guide de la techno-cité. Elle connaît chaque ruelle et chaque mot de passe Wi-Fi.'],
  'book-of-smoke': ['Книга дыма. Читать нужно быстро, пока страницы не развеялись.', 'A book of smoke. Read fast before the pages drift away.', 'ספר של עשן. צריך לקרוא מהר לפני שהדפים יתפזרו.', 'Un libro de humo. Hay que leerlo rápido, antes de que las páginas se disipen.', 'Un livre de fumée. Lisez vite, avant que les pages ne s’envolent.'],
  'mechanical-heart': ['Механическое сердце. Бьётся точно, но иногда требует смазки.', 'A mechanical heart. Beats precisely but now and then asks for oil.', 'לב מכני. פועם בדיוק, אבל לפעמים מבקש שמן.', 'Un corazón mecánico. Late con precisión, pero de vez en cuando pide aceite.', 'Un cœur mécanique. Il bat avec précision, mais réclame parfois de l’huile.'],
  'dust-meditation': ['Пылевая медитация. Главное — не чихнуть.', 'Dust meditation. The main thing is not to sneeze.', 'מדיטציית אבק. העיקר לא להתעטש.', 'Meditación de polvo. Lo principal es no estornudar.', 'Méditation de poussière. L’essentiel est de ne pas éternuer.'],
  'sun-forged-smile': ['Улыбка солнечной ковки. Приварена навсегда.', 'A sun-forged smile. Welded on for good.', 'חיוך מחושל בשמש. מרותך לתמיד.', 'Una sonrisa forjada al sol. Soldada para siempre.', 'Un sourire forgé au soleil. Soudé pour de bon.'],
  'pirate-of-the-frontier': ['Пират фронтира. Короткие пути знает все — длинные тоже, но не признаётся.', 'A frontier pirate. Knows every shortcut — and the long ways too, but will not admit it.', 'פיראט הגבול. מכיר כל קיצור דרך — וגם את הדרכים הארוכות, אבל לא מודה.', 'Un pirata de la frontera. Conoce todos los atajos — y también los caminos largos, pero no lo admitirá.', 'Un pirate des confins. Il connaît tous les raccourcis — et les longs détours aussi, mais il ne l’avouera pas.'],
  'forest-contact': ['Контакт в лесу. Обе стороны делают вид, что всё идёт по плану.', 'Contact in the forest. Both sides pretend everything is going to plan.', 'מגע ביער. שני הצדדים מעמידים פנים שהכול לפי התוכנית.', 'Contacto en el bosque. Ambas partes fingen que todo va según lo previsto.', 'Contact dans la forêt. Les deux camps font comme si tout se passait comme prévu.'],
  'orbital-acrobat': ['Орбитальный акробат. Сальто без гравитации засчитывается только с третьей попытки.', 'An orbital acrobat. A zero-gravity somersault counts only on the third try.', 'אקרובט במסלול. סלטה בלי כבידה נחשבת רק בניסיון השלישי.', 'Un acróbata orbital. Una voltereta en gravedad cero solo cuenta al tercer intento.', 'Un acrobate orbital. Un saut périlleux en apesanteur ne compte qu’au troisième essai.'],
  'red-suit-expedition': ['Экспедиция в красном. Видно издалека — особенно спасателям.', 'An expedition in red. Visible from afar — especially to rescuers.', 'משלחת באדום. נראית מרחוק — במיוחד לצוותי חילוץ.', 'Una expedición de rojo. Se ve desde lejos — sobre todo para los rescatistas.', 'Une expédition en rouge. Visible de loin — surtout pour les sauveteurs.'],
  'clockwork-inspector': ['Инспектор часового механизма. Проверяет время — и находит нарушения.', 'A clockwork inspector. Checks the time and always finds violations.', 'מפקחת שעון. בודקת את הזמן ותמיד מוצאת הפרות.', 'Un inspector de relojería. Revisa la hora y siempre encuentra infracciones.', 'Un inspecteur d’horlogerie. Il vérifie l’heure et trouve toujours des infractions.'],
  'root-haired-guardian': ['Страж с корнями вместо волос. Стрижка — только у садовника.', 'A guardian with roots for hair. Haircuts by the gardener only.', 'שומר עם שורשים במקום שיער. תספורת — רק אצל הגנן.', 'Un guardián con raíces en lugar de pelo. Solo se corta el pelo con el jardinero.', 'Un gardien aux racines en guise de cheveux. Coupe uniquement chez le jardinier.'],
  'waterline-gaze': ['Взгляд с ватерлинии. Тонуть при таком взгляде просто неловко.', 'A gaze from the waterline. Drowning under such a stare is simply awkward.', 'מבט מקו המים. לטבוע מול מבט כזה פשוט מביך.', 'Una mirada desde la línea de flotación. Ahogarse bajo esa mirada resulta, sencillamente, incómodo.', 'Un regard depuis la ligne de flottaison. Se noyer sous un tel regard serait tout simplement gênant.'],
  'racer-design-sheet': ['Чертёж скоростного корабля. Тормоза нарисуют в следующей версии.', 'A racing-ship design sheet. Brakes will be drawn in the next version.', 'שרטוט ספינת מרוץ. את הבלמים יציירו בגרסה הבאה.', 'Plano de una nave de carreras. Los frenos se dibujarán en la próxima versión.', 'Plan d’un vaisseau de course. Les freins seront dessinés dans la prochaine version.'],
  'silver-frontier-warden': ['Серебряный страж фронтира. Скидок не даёт, даже пиратам.', 'The silver frontier warden. Gives no discounts, not even to pirates.', 'השומרת הכסופה של הגבול. לא נותנת הנחות, אפילו לפיראטים.', 'El guardián plateado de la frontera. No hace descuentos, ni siquiera a los piratas.', 'Le gardien argenté des confins. Il n’accorde aucune remise, même aux pirates.'],
  'monolith-expedition': ['Экспедиция к монолиту. Монолит молчит, экспедиция тоже — из уважения.', 'An expedition to the monolith. The monolith is silent; so is the expedition, out of respect.', 'משלחת למונוליט. המונוליט שותק, וגם המשלחת — מתוך כבוד.', 'Una expedición al monolito. El monolito calla; la expedición también, por respeto.', 'Une expédition vers le monolithe. Le monolithe se tait ; l’expédition aussi, par respect.'],
  'horizon-palace': ['Дворец горизонта. Чем ближе подходишь, тем дальше он уходит.', 'The palace of the horizon. The closer you get, the further it moves.', 'ארמון האופק. ככל שמתקרבים, הוא מתרחק.', 'El palacio del horizonte. Cuanto más te acercas, más se aleja.', 'Le palais de l’horizon. Plus on s’en approche, plus il s’éloigne.'],
  'hanging-sky-garden': ['Подвесной небесный сад. Поливают его дождём по подписке.', 'A hanging sky garden. Watered by subscription rain.', 'גן שמיים תלוי. משקים אותו בגשם במנוי.', 'Un jardín celeste colgante. Se riega con lluvia por suscripción.', 'Un jardin céleste suspendu. On l’arrose avec de la pluie par abonnement.'],
  'library-ghost': ['Призрак библиотечного фонда. Выдаёт книги, которых уже никто не помнит.', 'The ghost of the library collection. Lends books that nobody remembers any more.', 'רוח אוסף הספרייה. משאילה ספרים שאיש כבר לא זוכר.', 'El fantasma de la colección de la biblioteca. Presta libros que ya nadie recuerda.', 'Le fantôme du fonds de la bibliothèque. Il prête des livres dont plus personne ne se souvient.'],
  'snow-field-mission': ['Снежная полевая миссия. Следы ведут туда, а возвращаться будем по другим.', 'A snow-field mission. The tracks lead there; we will come back by different ones.', 'משימת שדה בשלג. העקבות מובילות לשם, ונחזור בעקבות אחרות.', 'Una misión en el campo nevado. Las huellas llevan hasta allí; volveremos por otras.', 'Une mission sur le champ de neige. Les traces mènent là-bas ; nous reviendrons par d’autres.'],
  'solar-flower': ['Солнечный цветок. Поворачивается к свету, даже если свет — это вспышка камеры.', 'A solar flower. Turns towards the light, even if the light is a camera flash.', 'פרח שמש. פונה אל האור, גם אם האור הוא הבזק של מצלמה.', 'Una flor solar. Se gira hacia la luz, aunque la luz sea el flash de una cámara.', 'Une fleur solaire. Elle se tourne vers la lumière, même quand c’est un flash d’appareil photo.'],
  'electric-tide-guide': ['Проводница электрических приливов. После экскурсии волосы встают дыбом — бесплатно.', 'A guide of electric tides. After the tour your hair stands on end, free of charge.', 'מדריכת הגאות החשמלית. אחרי הסיור השיער סומר — בחינם.', 'Una guía de las mareas eléctricas. Tras la visita, el pelo se te pone de punta sin coste adicional.', 'Une guide des marées électriques. Après la visite, vos cheveux se dressent sur la tête, gratuitement.'],
  'moon-court-scholar': ['Учёная лунного двора. Считает звёзды и рассаживает гостей по созвездиям.', 'A scholar of the lunar court. Counts stars and seats guests by constellation.', 'מלומדת חצר הירח. סופרת כוכבים ומושיבה אורחים לפי קבוצות כוכבים.', 'Una erudita de la corte lunar. Cuenta estrellas y sienta a los invitados por constelaciones.', 'Une érudite de la cour lunaire. Elle compte les étoiles et place les invités par constellation.'],
  'neon-harbor-pilot': ['Пилот неоновой гавани. Паркуется по вывескам, чемоданы везёт робот.', 'A neon-harbour pilot. Parks by the signboards; a robot carries the bags.', 'טייסת נמל הניאון. חונה לפי השלטים, רובוט סוחב את המזוודות.', 'Un piloto del puerto de neón. Aparca guiándose por los letreros; las maletas las lleva un robot.', 'Un pilote du port des néons. Il se gare d’après les enseignes ; un robot porte les valises.'],
  'valley-of-the-listeners': ['Долина слушателей. Здесь слушают так внимательно, что тишина смущается.', 'The valley of listeners. They listen so closely that the silence gets embarrassed.', 'עמק המאזינים. מקשיבים כאן כל כך בתשומת לב שהשקט מתבייש.', 'El valle de los que escuchan. Escuchan con tanta atención que el silencio se avergüenza.', 'La vallée des auditeurs. Ils écoutent si attentivement que le silence en devient gêné.'],
  'skeletal-lecturer': ['Лектор без лишней плоти. Анатомию объясняет на собственном примере.', 'A lecturer without excess flesh. Explains anatomy using himself as the example.', 'מרצה בלי בשר מיותר. מסביר אנטומיה על עצמו.', 'Un profesor sin carne de sobra. Explica la anatomía con su propio ejemplo.', 'Un conférencier sans chair superflue. Il explique l’anatomie en prenant exemple sur lui-même.'],
  'armored-cat': ['Кот в тяжёлом скафандре. Мурлычет на частоте корабельной связи.', 'A cat in a heavy spacesuit. Purrs on the ship’s radio frequency.', 'חתול בחליפת חלל כבדה. מגרגר בתדר הקשר של הספינה.', 'Un gato con un traje espacial pesado. Ronronea en la frecuencia de radio de la nave.', 'Un chat en scaphandre lourd. Il ronronne sur la fréquence radio du vaisseau.'],
  'ancient-mechanical-guard': ['Древний механический страж. Девять жизней, четыре — в запасе.', 'An ancient mechanical guard. Nine lives, four still in reserve.', 'שומר מכני עתיק. תשע נשמות, ארבע עוד במלאי.', 'Un antiguo guardián mecánico. Nueve vidas, cuatro todavía en reserva.', 'Un ancien gardien mécanique. Neuf vies, dont quatre encore en réserve.'],
  'little-nova': ['Маленькая сверхновая. Пока маленькая, но уже вспыльчивая.', 'A little nova. Small for now, but already hot-tempered.', 'נובה קטנה. קטנה בינתיים, אבל כבר חמת מזג.', 'Una pequeña supernova. Pequeña por ahora, pero ya tiene mucho genio.', 'Une petite supernova. Petite pour l’instant, mais déjà colérique.'],
  'moonlit-traveler': ['Путница в лунном свете. Тень у неё длиннее дороги.', 'A traveller in moonlight. Her shadow is longer than the road.', 'מטיילת באור הירח. הצל שלה ארוך מהדרך.', 'Una viajera a la luz de la luna. Su sombra es más larga que el camino.', 'Une voyageuse au clair de lune. Son ombre est plus longue que la route.'],
};
